begin;
select no_plan();
update public.plans set prova_monthly_exams=null;
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000007801','education-parent@test.local'),('00000000-0000-4000-8000-000000007802','education-other@test.local');
insert into public.families(id,name,created_by) values ('10000000-0000-4000-8000-000000007801','A','00000000-0000-4000-8000-000000007801'),('10000000-0000-4000-8000-000000007802','B','00000000-0000-4000-8000-000000007802');
insert into public.family_members(family_id,user_id) values ('10000000-0000-4000-8000-000000007801','00000000-0000-4000-8000-000000007801'),('10000000-0000-4000-8000-000000007802','00000000-0000-4000-8000-000000007802');
insert into public.children(id,family_id,name,grade) values ('20000000-0000-4000-8000-000000007801','10000000-0000-4000-8000-000000007801','Ece',2),('20000000-0000-4000-8000-000000007802','10000000-0000-4000-8000-000000007801','Can',5);
insert into public.exams(id,family_id,child_id,title,subject,grade) values ('40000000-0000-4000-8000-000000007801','10000000-0000-4000-8000-000000007801','20000000-0000-4000-8000-000000007801','Old exam','Matematik',2);
create function pg_temp.ch() returns uuid language sql as $$select '20000000-0000-4000-8000-000000007801'::uuid$$;
create function pg_temp.year() returns integer language sql as $$select extract(year from now())::int$$;
create function pg_temp.first_day() returns date language sql as $$select make_date(pg_temp.year()-1,9,1)$$;
create function pg_temp.next_day() returns date language sql as $$select make_date(pg_temp.year(),1,1)$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000007801","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000007801","role":"parent"}}',true);
select is(public.get_child_education(pg_temp.ch())->>'revision','0','no guessed historical period for existing child');
select is(public.get_child_education(pg_temp.ch())->'current','null'::jsonb,'no inferred date or academic year');
select lives_ok($$select public.save_school_timetable(pg_temp.ch(),0,'[{"id":"math","day":1,"title":"Matematik","start":"09:00","end":"09:40"}]','{"start":"09:00","duration":40,"break":10}')$$,'existing timetable');
select lives_ok($$select public.change_child_education('70000000-0000-4000-8000-000000007801',pg_temp.ch(),0,'initial',pg_temp.year()-1,2,'İlk Okul',pg_temp.first_day(),1,true)$$,'initial period confirmed by parent');
select is(public.get_child_education(pg_temp.ch())->>'revision','1','initial version increments');
select lives_ok($$select public.change_child_education('70000000-0000-4000-8000-000000007801',pg_temp.ch(),0,'initial',pg_temp.year()-1,2,'İlk Okul',pg_temp.first_day(),1,true)$$,'lost response retry succeeds');
select is(public.get_child_education(pg_temp.ch())->>'revision','1','retry does not create duplicate period');
select throws_ok($$select public.change_child_education('70000000-0000-4000-8000-000000007801',pg_temp.ch(),0,'initial',pg_temp.year()-1,3,'İlk Okul',pg_temp.first_day(),1,true)$$,'P0001','request_conflict','request payload cannot change');
select throws_ok($$update public.children set grade=3 where id=pg_temp.ch()$$,'P0001','education_use_transition','old client cannot bypass managed period');
select lives_ok($$update public.children set name='Ece updated' where id=pg_temp.ch()$$,'non-education profile edits stay compatible');
insert into public.exams(id,family_id,child_id,title,subject,grade) values ('40000000-0000-4000-8000-000000007802','10000000-0000-4000-8000-000000007801',pg_temp.ch(),'Recorded exam','Matematik',2);
select is((select education_context->>'grade' from public.exams where id='40000000-0000-4000-8000-000000007802'),'2','new exam freezes education context');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),0,'new_year',pg_temp.year(),3,'İlk Okul',pg_temp.next_day(),1,false)$$,'P0001','education_changed','stale period editor rejected');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),1,'new_year',pg_temp.year(),3,'İlk Okul',pg_temp.next_day(),0,false)$$,'P0001','timetable_conflict','concurrent timetable change must be reviewed');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),1,'new_year',pg_temp.year()+1,3,'İlk Okul',make_date(pg_temp.year()+1,9,1),1,false)$$,'P0001','education_date','future changes not silently applied today');
select lives_ok($$select public.change_child_education('70000000-0000-4000-8000-000000007802',pg_temp.ch(),1,'new_year',pg_temp.year(),3,'İlk Okul',pg_temp.next_day(),1,false)$$,'new year archives program and starts empty');
select is((select grade::int from public.children where id=pg_temp.ch()),3,'current grade used by curriculum now updated');
select is((select grade::int from public.children where id='20000000-0000-4000-8000-000000007802'),5,'sibling unchanged');
select is(public.get_child_education(pg_temp.ch())->'timetable'->'lessons','[]'::jsonb,'new program empty');
select is(public.get_child_education(pg_temp.ch())->'history'->0->'timetable_snapshot'->'lessons'->0->>'title','Matematik','previous program retained readably');
select is(public.get_child_education(pg_temp.ch())->'history'->0->>'grade','2','previous grade retained');
select is(public.get_child_education(pg_temp.ch())->'timetable'->'settings','{"start":"09:00","duration":40,"break":10}'::jsonb,'bell settings retained');
select is((select count(*)::int from public.events where child_id=pg_temp.ch() and timetable_entry_key is not null),0,'clear reconciles timetable-owned events');
select is((select education_context from public.exams where id='40000000-0000-4000-8000-000000007801'),null::jsonb,'old evidence remains unknown');
select is((select education_context->>'grade' from public.exams where id='40000000-0000-4000-8000-000000007802'),'2','earlier evidence not relabelled after transition');
select lives_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),2,'transfer',pg_temp.year(),3,'Yeni Okul',pg_temp.next_day()+1,2,true)$$,'school transfer preserves grade and period year');
select is(jsonb_array_length(public.get_child_education(pg_temp.ch())->'history'),2,'school move adds dated history');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),3,'transfer',pg_temp.year(),4,'Başka Okul',pg_temp.next_day()+2,2,true)$$,'P0001','education_transfer','transfer cannot also silently promote grade');
select lives_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),3,'correct',pg_temp.year(),4,'Düzeltilmiş Okul',pg_temp.next_day()+1,2,true)$$,'explicit correction of current information');
select is(jsonb_array_length(public.get_child_education(pg_temp.ch())->'history'),2,'correction does not create false school transition');
select is(public.get_child_education(pg_temp.ch())->'corrections'->0->'before'->>'grade','3','correction audit preserves previous information');
select is(public.get_child_education(pg_temp.ch())->'current'->>'grade','4','correction updates current projection');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),4,'correct',pg_temp.year(),4,'Düzeltilmiş Okul',pg_temp.next_day()+2,2,true)$$,'P0001','education_date','correction cannot shift established boundaries');
select lives_ok($$select public.change_child_education('70000000-0000-4000-8000-000000007802',pg_temp.ch(),1,'new_year',pg_temp.year(),3,'İlk Okul',pg_temp.next_day(),1,false)$$,'old receipt remains replayable');
select is(public.get_child_education(pg_temp.ch())->'current'->>'grade','4','old replay does not undo later correction');
select is((select count(*)::int from public.exams where child_id=pg_temp.ch()),2,'transition keeps exams');
select ok(not has_function_privilege('anon','public.get_child_education(uuid)','execute'),'anonymous no education history');
select ok(not has_table_privilege('authenticated','gina.child_education_periods','UPDATE'),'cannot directly rewrite history');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000007802","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000007802","role":"parent"}}',true);
select throws_ok($$select public.get_child_education(pg_temp.ch())$$,'42501','education_forbidden','other family cannot read history');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),4,'correct',pg_temp.year(),4,'Other',pg_temp.next_day()+1,2,true)$$,'42501','education_forbidden','other family cannot change history');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000007801","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000007801","role":"child"}}',true);
select throws_ok($$select public.get_child_education(pg_temp.ch())$$,'42501','education_forbidden','child cannot access parent management');
select throws_ok($$select public.change_child_education(gen_random_uuid(),pg_temp.ch(),4,'correct',pg_temp.year(),4,'Other',pg_temp.next_day()+1,2,true)$$,'42501','education_forbidden','child cannot promote own grade');
select * from finish();
rollback;
